    "logicalThinking": {
      "score": 55,
      "feedback": "문제 상황 인지와 중재 시도를 언급했으나, 구체적인 논리 전개나 문제 해결 과정이 명확하지 않음."
    },
    "specificity": {
      "score": 40,
      "feedback": "상황, 역할, 행동, 결과에 대한 구체적인 설명이 부족하여 답변이 추상적임."
    },
    "communication": {
      "score": 60,
      "feedback": "간결하고 존중하는 어조로 답변했으나, 더 명확하고 체계적인 전달이 필요함."
    },
    "jobFit": {
      "score": 55,
      "feedback": "팀워크와 소통의 중요성을 인지한 점은 긍정적이나, 실제 행동과 결과에 대한 구체적 사례 부족으로 직무 적합성 판단이 어려움."
    },
    "starStructure": {
      "score": 50,
      "feedback": "STAR 구조 중 상황과 결과는 간략히 언급했으나, 구체적인 행동과 역할이 부족해 체계적인 답변으로 보기 어려움."
    }
  },
  "strengths": [
    "팀 내 의견 충돌 상황을 인지하고 중재하려는 태도",
    "소통의 중요성을 인지하고 있음",
    "간결하고 존중하는 커뮤니케이션 스타일"
  ],
  "weaknesses": [
    "구체적인 상황과 본인의 역할, 행동에 대한 설명 부족",
    "문제 해결 과정과 결과에 대한 상세한 서술 미흡",
    "STAR 구조에 맞춘 체계적인 답변 부족"
  ]
}

